//! Opt-in, user-session D-Bus activation for shun's public resident control API.

use crate::{cli, control, desktop};
use std::io::Write as _;
use std::path::{Path, PathBuf};

const MARKER: &str =
    "# Generated by shun (niri control activation); remove this line to keep your own edits.";

#[derive(Debug, PartialEq, Eq)]
enum Installed {
    Created,
    Updated,
    UpToDate,
    UserOwned,
}

/// D-Bus service files have two parsing layers, not `.desktop` Exec field codes:
/// `bus/desktop-file.c` unescapes the string, then `dbus/dbus-shell.c` parses argv.
/// See https://github.com/d-bus/dbus/blob/master/bus/desktop-file.c and
/// https://github.com/d-bus/dbus/blob/master/dbus/dbus-shell.c.
/// Quote one argv word, then escape its backslashes for the service-file layer.
/// Neither layer executes a shell; apostrophes and percent signs remain literal.
fn exec_quote(exe: &Path) -> Result<String, String> {
    if !exe.is_absolute() {
        return Err("D-Bus activation executable path must be absolute".into());
    }
    let exe = exe.to_str().ok_or("shun executable path is not UTF-8")?;
    if exe.contains('\0') {
        return Err("shun executable path contains NUL".into());
    }
    let mut out = String::from("\"");
    for c in exe.chars() {
        match c {
            '"' | '$' | '`' => {
                out.push_str("\\\\");
                out.push(c);
            }
            '\\' => out.push_str("\\\\\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    Ok(out)
}

fn render(exe: &Path) -> Result<String, String> {
    Ok(format!(
        "{MARKER}\n[D-BUS Service]\nName={}\nExec={} {}\n",
        control::BUS_NAME,
        exec_quote(exe)?,
        cli::RESIDENT_ARG
    ))
}

fn read_optional(path: &Path) -> Result<Option<Vec<u8>>, String> {
    match std::fs::read(path) {
        Ok(bytes) => Ok(Some(bytes)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(format!("read {}: {e}", path.display())),
    }
}

fn resolved_output(path: &Path) -> Result<PathBuf, String> {
    match std::fs::canonicalize(path) {
        Ok(target) => Ok(target),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if std::fs::symlink_metadata(path).is_ok() {
                return Err("D-Bus activation descriptor is a dangling symlink".into());
            }
            let parent = path.parent().ok_or("activation descriptor has no parent")?;
            Ok(std::fs::canonicalize(parent)
                .map_err(|e| e.to_string())?
                .join(
                    path.file_name()
                        .ok_or("activation descriptor has no filename")?,
                ))
        }
        Err(e) => Err(format!("resolve {}: {e}", path.display())),
    }
}

fn install_into(data_dir: &Path, exe: &Path) -> Result<Installed, String> {
    let wanted = render(exe)?;
    let directory = data_dir.join("dbus-1/services");
    let entry = directory.join(format!("{}.service", control::BUS_NAME));
    std::fs::create_dir_all(&directory)
        .map_err(|e| format!("create {}: {e}", directory.display()))?;
    let target = resolved_output(&entry)?;
    let original = read_optional(&entry)?;
    let status = match original.as_deref() {
        Some(current) if current == wanted.as_bytes() => return Ok(Installed::UpToDate),
        Some(current)
            if !current
                .split(|&b| b == b'\n')
                .any(|line| line == MARKER.as_bytes()) =>
        {
            return Ok(Installed::UserOwned);
        }
        Some(_) => Installed::Updated,
        None => Installed::Created,
    };
    // Stage beside the resolved output: symlinks and cross-filesystem dotfiles are preserved.
    let mut staged = tempfile::Builder::new()
        .prefix(".shun-control-")
        .tempfile_in(target.parent().ok_or("activation target has no parent")?)
        .map_err(|e| format!("stage activation descriptor: {e}"))?;
    staged
        .write_all(wanted.as_bytes())
        .map_err(|e| e.to_string())?;
    let permissions = if original.is_some() {
        std::fs::metadata(&target)
            .map_err(|e| e.to_string())?
            .permissions()
    } else {
        use std::os::unix::fs::PermissionsExt;
        std::fs::Permissions::from_mode(0o644)
    };
    staged
        .as_file()
        .set_permissions(permissions)
        .map_err(|e| e.to_string())?;
    if resolved_output(&entry)? != target || read_optional(&entry)? != original {
        return Err("D-Bus activation descriptor changed; no changes written".into());
    }
    if original.is_some() {
        staged
            .persist(&target)
            .map_err(|e| format!("replace activation descriptor: {e}"))?;
    } else {
        // Do not replace a user file created after the absence check.
        staged
            .persist_noclobber(&target)
            .map_err(|e| format!("create activation descriptor: {e}"))?;
    }
    Ok(status)
}

/// Called only by opted-in niri synchronization, never by default startup.
/// Bootstrap-only mode never acts, even when another process is still acquiring the name.
pub(crate) fn install() -> Result<(), String> {
    let data = dirs_next::data_dir().ok_or("cannot resolve the user data dir")?;
    let exe = desktop::exe_path().ok_or("cannot resolve the shun executable path")?;
    match install_into(&data, &exe)? {
        Installed::Created | Installed::Updated => log::info!("shun control activation installed"),
        Installed::UserOwned => log::warn!(
            "shun control activation: user-maintained {}.service left untouched",
            control::BUS_NAME
        ),
        Installed::UpToDate => {}
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(data: &Path) -> PathBuf {
        data.join("dbus-1/services/com.yukimemi.shun.Control.service")
    }

    #[test]
    fn installs_updates_and_preserves_user_descriptors_and_unchanged_inode() {
        use std::os::unix::fs::MetadataExt;
        let data = tempfile::tempdir().unwrap();
        let exe = Path::new("/opt/my apps/it's \"shun\"\\100%.AppImage");
        assert_eq!(install_into(data.path(), exe).unwrap(), Installed::Created);
        let path = entry(data.path());
        let text = std::fs::read_to_string(&path).unwrap();
        assert!(text.contains("\nName=com.yukimemi.shun.Control\n"));
        let inode = std::fs::metadata(&path).unwrap().ino();
        assert_eq!(install_into(data.path(), exe).unwrap(), Installed::UpToDate);
        assert_eq!(std::fs::metadata(&path).unwrap().ino(), inode);
        assert_eq!(
            install_into(data.path(), Path::new("/new/shun")).unwrap(),
            Installed::Updated
        );
        let user = "[D-BUS Service]\nName=com.yukimemi.shun.Control\nExec=/my/shun\n";
        std::fs::write(&path, user).unwrap();
        assert_eq!(
            install_into(data.path(), exe).unwrap(),
            Installed::UserOwned
        );
        assert_eq!(std::fs::read_to_string(&path).unwrap(), user);
        std::fs::write(&path, b"user-owned non-UTF8 \xff").unwrap();
        assert_eq!(
            install_into(data.path(), exe).unwrap(),
            Installed::UserOwned
        );
        assert_eq!(std::fs::read(&path).unwrap(), b"user-owned non-UTF8 \xff");
    }

    #[test]
    fn preserves_symlink_target_and_permissions_and_rejects_dangling_symlink() {
        use std::os::unix::fs::{symlink, PermissionsExt};
        let data = tempfile::tempdir().unwrap();
        let targets = tempfile::tempdir().unwrap();
        let target = targets.path().join("activation.service");
        let exe = Path::new("/opt/shun.AppImage");
        std::fs::write(&target, render(Path::new("/old/shun")).unwrap()).unwrap();
        std::fs::set_permissions(&target, std::fs::Permissions::from_mode(0o640)).unwrap();
        let path = entry(data.path());
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        symlink(&target, &path).unwrap();
        assert_eq!(install_into(data.path(), exe).unwrap(), Installed::Updated);
        assert_eq!(std::fs::read_link(&path).unwrap(), target);
        assert_eq!(
            std::fs::read_to_string(&target).unwrap(),
            render(exe).unwrap()
        );
        assert_eq!(
            std::fs::metadata(&target).unwrap().permissions().mode() & 0o777,
            0o640
        );
        std::fs::remove_file(&target).unwrap();
        assert!(install_into(data.path(), exe).is_err());
        assert_eq!(std::fs::read_link(&path).unwrap(), target);
        assert!(!target.exists());
    }

    #[test]
    fn invalid_executable_does_not_create_descriptor_directory() {
        use std::ffi::OsStr;
        use std::os::unix::ffi::OsStrExt;
        let data = tempfile::tempdir().unwrap();
        for exe in [
            Path::new("relative/shun"),
            Path::new("/nul\0shun"),
            Path::new(OsStr::from_bytes(b"/bad\xff")),
        ] {
            assert!(install_into(data.path(), exe).is_err());
        }
        assert!(!data.path().join("dbus-1").exists());
    }

    #[test]
    #[ignore = "requires dbus-run-session and busctl; starts only a private bus and temporary executable"]
    fn real_dbus_activation_parses_special_path_and_passes_only_resident_mode() {
        use std::os::unix::fs::PermissionsExt;
        use std::process::Command;
        let root = tempfile::tempdir().unwrap();
        let data = root.path().join("data");
        let exe = root.path().join("it's \"shun\"\\$`100%.AppImage");
        // This executable deliberately never owns the bus name. Activation's expected error
        // lets the test inspect the actual argv delivered by dbus-daemon, not a parser mock.
        std::fs::write(
            &exe,
            "#!/bin/sh\nprintf '%s\\n' \"$#\" \"$@\" >> \"$XDG_DATA_HOME/activation-args\"\n",
        )
        .unwrap();
        std::fs::set_permissions(&exe, std::fs::Permissions::from_mode(0o700)).unwrap();
        assert_eq!(install_into(&data, &exe).unwrap(), Installed::Created);
        let output = Command::new("dbus-run-session")
            .args([
                "--",
                "busctl",
                "--user",
                "--quiet",
                "--timeout=5",
                "call",
                "com.yukimemi.shun.Control",
                "/com/yukimemi/shun/Control",
                "com.yukimemi.shun.Control1",
                "Toggle",
            ])
            .env_remove("DBUS_SESSION_BUS_ADDRESS")
            .env("HOME", root.path())
            .env("XDG_DATA_HOME", &data)
            .env("XDG_DATA_DIRS", root.path().join("empty-data"))
            .env("XDG_CONFIG_HOME", root.path().join("config"))
            .env("XDG_CACHE_HOME", root.path().join("cache"))
            .output()
            .expect("dbus-run-session must be installed");
        assert!(
            !output.status.success(),
            "probe executable must not own the bus name"
        );
        assert_eq!(
            std::fs::read_to_string(data.join("activation-args")).unwrap_or_else(|error| {
                panic!("activation did not reach the executable: {error}; {}", String::from_utf8_lossy(&output.stderr))
            }),
            "1\n--resident\n",
            "one activation, with only bootstrap mode and no startup action to duplicate the queued method"
        );
    }
}
